<?php
// ============================================================
// KAIROS.PHP — Saisie vocale rapide d'un Kairos
// Accessible via lien secret sur Android
// ============================================================
$TOKEN = 'pharmacie-lempdes-cron-2026';

// API : réception d'un Kairos
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    header('Content-Type: application/json');
    $data = json_decode(file_get_contents('php://input'), true) ?? [];
    if (($data['token'] ?? '') !== $TOKEN) {
        echo json_encode(['ok' => false, 'error' => 'Accès refusé']); exit;
    }
    $txt = trim($data['txt'] ?? '');
    if (!$txt) { echo json_encode(['ok' => false, 'error' => 'Texte vide']); exit; }

    $file = __DIR__ . '/planning_data.json';
    $state = json_decode(file_get_contents($file), true) ?? [];
    if (!isset($state['mnemosyne'])) $state['mnemosyne'] = ['kairos' => [], 'rites' => [], 'fils' => []];
    if (!isset($state['mnemosyne']['kairos'])) $state['mnemosyne']['kairos'] = [];

    array_unshift($state['mnemosyne']['kairos'], [
        'id'       => 'k' . time() . rand(100, 999),
        'txt'      => $txt,
        'done'     => false,
        'postpones'=> 0,
        'date'     => date('c'),
    ]);

    file_put_contents($file, json_encode($state, JSON_UNESCAPED_UNICODE | JSON_PRETTY_PRINT));
    echo json_encode(['ok' => true, 'txt' => $txt]);
    exit;
}

// Vérification token GET
if (($_GET['t'] ?? '') !== $TOKEN) {
    http_response_code(403); echo 'Accès refusé'; exit;
}
?>
<!DOCTYPE html>
<html lang="fr">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1, maximum-scale=1">
<meta name="mobile-web-app-capable" content="yes">
<meta name="apple-mobile-web-app-capable" content="yes">
<meta name="apple-mobile-web-app-title" content="Kairos">
<link rel="apple-touch-icon" href="data:image/png;base64,">
<link rel="icon" type="image/png" href="data:image/png;base64,">
<link rel="manifest" href="data:application/json;base64,">
<title>⚡ Kairos</title>
<style>
  *{margin:0;padding:0;box-sizing:border-box}
  body{font-family:Arial,sans-serif;background:linear-gradient(135deg,#1a0a2e,#2d1a5c);min-height:100vh;display:flex;flex-direction:column;align-items:center;justify-content:center;padding:20px;color:#fff}
  .logo{font-size:3rem;margin-bottom:8px}
  h1{font-size:1.3rem;font-weight:700;margin-bottom:4px;letter-spacing:.5px}
  .sub{font-size:.8rem;opacity:.6;margin-bottom:32px}
  #micBtn{width:120px;height:120px;border-radius:50%;border:none;background:linear-gradient(135deg,#5B2D8E,#3DB830);cursor:pointer;font-size:3rem;box-shadow:0 8px 32px rgba(91,45,142,.5);transition:all .2s;display:flex;align-items:center;justify-content:center;margin-bottom:24px}
  #micBtn.listening{animation:pulse 1s infinite;background:linear-gradient(135deg,#c0392b,#e74c3c)}
  @keyframes pulse{0%,100%{transform:scale(1)}50%{transform:scale(1.08)}}
  #transcript{width:100%;max-width:360px;min-height:60px;background:rgba(255,255,255,.1);border:2px solid rgba(255,255,255,.2);border-radius:16px;padding:14px;font-size:1rem;color:#fff;text-align:center;margin-bottom:16px;line-height:1.5}
  #transcript.placeholder{opacity:.4;font-style:italic}
  #sendBtn{width:100%;max-width:360px;padding:16px;border-radius:16px;border:none;background:linear-gradient(135deg,#3DB830,#27ae60);color:#fff;font-size:1.1rem;font-weight:700;cursor:pointer;box-shadow:0 4px 16px rgba(61,184,48,.4);display:none}
  #sendBtn:active{transform:scale(.97)}
  #status{margin-top:16px;font-size:.85rem;opacity:.7;text-align:center;min-height:24px}
  #recentList{width:100%;max-width:360px;margin-top:24px}
  .recent-item{background:rgba(255,255,255,.08);border-radius:10px;padding:10px 14px;margin-bottom:8px;font-size:.85rem;border-left:3px solid #3DB830}
  .hint{font-size:.75rem;opacity:.5;margin-top:8px;text-align:center}
</style>
</head>
<body>
<img src="data:image/png;base64," style="width:100px;height:100px;border-radius:50%;box-shadow:0 4px 20px rgba(91,45,142,.5);margin-bottom:8px">
<h1>Kairos</h1>
<div class="sub">Pharmacie du Marais</div>

<button id="micBtn" onclick="toggleMic()">🎤</button>
<div id="transcript" class="placeholder">Appuyez sur le micro et parlez...</div>
<button id="sendBtn" onclick="sendKairos()">Envoyer ⚡</button>
<div id="status"></div>

<div id="recentList"></div>
<div class="hint">Ajoutez ce lien en raccourci sur votre écran d'accueil</div>

<script>
const TOKEN = '<?= $TOKEN ?>';
let recognition = null;
let currentText = '';
let listening = false;
const recent = JSON.parse(localStorage.getItem('kairosRecent') || '[]');

function renderRecent() {
  const el = document.getElementById('recentList');
  if (!recent.length) { el.innerHTML = ''; return; }
  el.innerHTML = '<div style="font-size:.72rem;opacity:.5;margin-bottom:8px;text-align:center">Envoyés récemment</div>'
    + recent.slice(0, 3).map(t => `<div class="recent-item">${t}</div>`).join('');
}
renderRecent();

function toggleMic() {
  if (listening) { stopMic(); return; }
  if (!('webkitSpeechRecognition' in window) && !('SpeechRecognition' in window)) {
    setStatus('❌ Reconnaissance vocale non supportée sur ce navigateur'); return;
  }
  const SR = window.SpeechRecognition || window.webkitSpeechRecognition;
  recognition = new SR();
  recognition.lang = 'fr-FR';
  recognition.continuous = false;
  recognition.interimResults = true;
  recognition.onstart = () => {
    listening = true;
    document.getElementById('micBtn').classList.add('listening');
    document.getElementById('micBtn').textContent = '⏹';
    setStatus('🎤 Parlez...');
  };
  recognition.onresult = (e) => {
    let interim = '', final = '';
    for (let i = e.resultIndex; i < e.results.length; i++) {
      if (e.results[i].isFinal) final += e.results[i][0].transcript;
      else interim += e.results[i][0].transcript;
    }
    currentText = final || interim;
    const el = document.getElementById('transcript');
    el.textContent = currentText;
    el.classList.remove('placeholder');
    if (final) {
      document.getElementById('sendBtn').style.display = 'block';
    }
  };
  recognition.onerror = (e) => { setStatus('❌ Erreur : ' + e.error); stopMic(); };
  recognition.onend = () => { stopMic(); };
  recognition.start();
}

function stopMic() {
  listening = false;
  if (recognition) recognition.stop();
  document.getElementById('micBtn').classList.remove('listening');
  document.getElementById('micBtn').textContent = '🎤';
  if (currentText) document.getElementById('sendBtn').style.display = 'block';
  setStatus('');
}

async function sendKairos() {
  if (!currentText.trim()) return;
  setStatus('⏳ Envoi en cours...');
  document.getElementById('sendBtn').disabled = true;
  try {
    const r = await fetch('kairos.php?t=<?= $TOKEN ?>', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ token: TOKEN, txt: currentText.trim() })
    });
    const d = await r.json();
    if (d.ok) {
      setStatus('✅ Kairos créé !');
      recent.unshift(currentText.trim());
      localStorage.setItem('kairosRecent', JSON.stringify(recent.slice(0, 10)));
      renderRecent();
      currentText = '';
      const el = document.getElementById('transcript');
      el.textContent = 'Appuyez sur le micro et parlez...';
      el.classList.add('placeholder');
      document.getElementById('sendBtn').style.display = 'none';
      setTimeout(() => setStatus(''), 2000);
    } else {
      setStatus('❌ ' + (d.error || 'Erreur'));
    }
  } catch(e) {
    setStatus('❌ ' + e.message);
  }
  document.getElementById('sendBtn').disabled = false;
}

function setStatus(txt) { document.getElementById('status').textContent = txt; }
</script>
</body>
</html>
